    void restore(SharedPreferences prefs,Map<String,?> original){SharedPreferences.Editor edit=prefs.edit().clear();for(Map.Entry<String,?> item:original.entrySet()){Object value=item.getValue();String key=item.getKey();if(value instanceof String)edit.putString(key,(String)value);else if(value instanceof Boolean)edit.putBoolean(key,(Boolean)value);else if(value instanceof Integer)edit.putInt(key,(Integer)value);else if(value instanceof Long)edit.putLong(key,(Long)value);else if(value instanceof Float)edit.putFloat(key,(Float)value);else if(value instanceof Set)edit.putStringSet(key,(Set<String>)value);}edit.commit();}
    void run()throws Exception{
        SharedPreferences prefs=context.getSharedPreferences("library",0);Map<String,?> original=new HashMap<>(prefs.getAll());prefs.edit().putString("player_theme","legacy").remove("selected_source").putBoolean("auto_cache",false).putInt(PlayerBackground.MODE,0).putInt("lyrics_style",4).putInt("lyrics_size",100).putInt("lyrics_spacing",75).putInt("lyrics_color",1).putBoolean("lyrics_centered",true).putBoolean("lyrics_translation",true).putBoolean("lyrics_reduce_motion",false).commit();
        MainActivity activity=(MainActivity)test.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));PlaybackService[] connected={null};helper.await(()->{connected[0]=(PlaybackService)FullPortChecks.field(activity,"playbackService");return connected[0]!=null;},"record lyric service missing");PlaybackService service=connected[0];NowPlayingDialog[] page={null};File art=new File(context.getCacheDir(),"record-lyrics-art.png");ArrayList<String> uris=new ArrayList<>();NativeAudioChecks audio=new NativeAudioChecks(test);
        try(NativeAudioChecks.Server server=audio.new Server(false)){
            Bitmap cover=Bitmap.createBitmap(320,320,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(cover);Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);paint.setShader(new LinearGradient(0,0,320,320,0xff2c7c83,0xff799198,Shader.TileMode.CLAMP));canvas.drawPaint(paint);paint.setShader(null);paint.setColor(0x5595d3d7);canvas.drawCircle(80,250,145,paint);try(FileOutputStream out=new FileOutputStream(art)){cover.compress(Bitmap.CompressFormat.PNG,100,out);}finally{cover.recycle();}
            JSONArray queue=new JSONArray();for(int i=0;i<2;i++){String uri=server.base()+"/quality-aac.m4a?record-lyrics="+i;uris.add(uri);JSONObject track=new JSONObject().put("name",i==0?"晚风":"湖岸").put("artists",new JSONArray().put(new JSONObject().put("name","唱片歌词测试"))).put("album",new JSONObject().put("imageUrl",art.toURI().toString()));queue.put(new JSONObject().put("uri",uri).put("title",i==0?"晚风":"湖岸").put("track",track));}
            actions.ui(()->{HashMap<String,String> saved=(HashMap<String,String>)FullPortChecks.field(activity,"localLyrics");for(String uri:uris)saved.put(uri,"[00:00.00]晚风轻轻走过湖岸\n[00:02.00]把每一句旋律留给你\n[00:04.00]让心情跟着唱片转动\n[00:06.00]沿着星光慢慢向前\n[00:08.00]还有熟悉温柔的声音\n[00:12.00]让每一次播放更加从容");service.clearQueue();PlaybackService.startQueue(context,queue,0,0,68,false,false,"high");});helper.await(()->service.snapshot().ready&&service.snapshot().playing&&service.snapshot().position>100,"record lyric audio did not start");actions.ui(service::pause);PlaybackService.Snapshot before=service.snapshot();
            actions.ui(()->{((ImageView)FullPortChecks.field(activity,"coverArt")).performClick();page[0]=(NowPlayingDialog)FullPortChecks.field(activity,"nowPlayingDialog");});helper.await(()->page[0]!=null&&page[0].stage.timeline().lines.size()==6&&(Boolean)FullPortChecks.field(page[0].stage,"renderActive"),"inline lyric page did not load or regain foreground");
            actions.ui(()->{check(page[0].lyrics.performLongClick(),"lyric control has no long-press settings");});helper.await(()->{AlertDialog dialog=(AlertDialog)FullPortChecks.field(page[0],"lyricSettingsDialog");return dialog!=null&&dialog.isShowing()&&!(Boolean)FullPortChecks.field(page[0].stage,"renderActive");},"real settings did not stop covered lyric animation");
            actions.ui(()->{AlertDialog dialog=(AlertDialog)FullPortChecks.field(page[0],"lyricSettingsDialog");View root=dialog.getWindow().getDecorView();((Spinner)tagged(root,"record-lyric-style")).setSelection(6);((Spinner)tagged(root,"record-lyric-color")).setSelection(2);SeekBar size=(SeekBar)tagged(root,"lyrics_size");size.onKeyDown(KeyEvent.KEYCODE_DPAD_RIGHT,new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_RIGHT));((Switch)tagged(root,"lyrics_translation")).performClick();((Switch)tagged(root,"lyrics_centered")).performClick();((Switch)tagged(root,"lyrics_reduce_motion")).performClick();});
            helper.await(()->page[0].stage.appearance().style==6&&page[0].stage.appearance().color==2&&page[0].stage.appearance().size>100&&page[0].stage.appearance().reduceMotion&&!page[0].stage.appearance().translation&&!page[0].stage.appearance().centered,"real settings widgets did not update/persist inline rendering");check(prefs.getInt("lyrics_style",-1)==6&&prefs.getInt("lyrics_size",0)==page[0].stage.appearance().size&&!(Boolean)FullPortChecks.field(page[0].cover,"motion"),"settings did not reach preferences or record motion");actions.screenshot("record-lyrics-settings.png");SourcePlaylistUiChecks.click(test,"完成");helper.await(()->(Boolean)FullPortChecks.field(page[0].stage,"renderActive"),"closing settings did not resume visible lyric rendering");
            actions.ui(()->page[0].lyrics.performClick());LyricsStageDialog[] full={null};helper.await(()->{full[0]=(LyricsStageDialog)FullPortChecks.field(activity,"lyricsStage");return full[0]!=null&&full[0].isShowing()&&full[0].stage.timeline().lines.size()==6;},"full lyrics page did not reuse saved timeline");check(full[0].stage.appearance().style==6&&full[0].stage.appearance().size==prefs.getInt("lyrics_size",0),"full lyrics page ignored inline settings");
            actions.ui(()->NowPlayingChecks.invoke(full[0],"showTiming"));SourcePlaylistUiChecks.click(test,"延后 0.2 秒");helper.await(()->page[0].timing.offset()==200&&full[0].timing.offset()==200,"full-page per-track timing did not synchronize with record page");SourcePlaylistUiChecks.click(test,"完成");actions.ui(()->NowPlayingChecks.invoke(full[0],"showAppearance"));actions.ui(()->{AlertDialog dialog=(AlertDialog)FullPortChecks.field(full[0],"appearanceDialog");((Spinner)tagged(dialog.getWindow().getDecorView(),"显示样式")).setSelection(13);});helper.await(()->page[0].stage.appearance().style==13,"full-page style change did not reach covered record page");SourcePlaylistUiChecks.click(test,"完成");actions.ui(full[0]::dismiss);helper.await(()->(Boolean)FullPortChecks.field(page[0].stage,"renderActive"),"return from full lyrics left inline animation inactive");check(service.snapshot().player==before.player&&service.snapshot().generation==before.generation&&Math.abs(service.snapshot().position-before.position)<150,"lyric settings or timing restarted/sought paused audio");
            actions.ui(()->page[0].showLyricSettings());SourcePlaylistUiChecks.click(test,"恢复默认");helper.await(()->page[0].stage.appearance().style==4&&page[0].stage.appearance().size==100&&page[0].stage.appearance().spacing==75&&!page[0].stage.appearance().reduceMotion&&(Boolean)FullPortChecks.field(page[0].stage,"renderActive")&&!((AlertDialog)FullPortChecks.field(page[0],"lyricSettingsDialog")).isShowing(),"inline display defaults did not apply");check(page[0].timing.offset()==200,"display defaults erased per-track synchronization");test.waitForIdleSync();int beforeCancel=service.snapshot().position;actions.ui(()->{actions.event(page[0].stage,MotionEvent.ACTION_DOWN,page[0].stage.getWidth()/2f,page[0].stage.getHeight()*.7f);actions.event(page[0].stage,MotionEvent.ACTION_CANCEL,page[0].stage.getWidth()/2f,page[0].stage.getHeight()*.7f);actions.event(page[0].stage,MotionEvent.ACTION_UP,page[0].stage.getWidth()/2f,page[0].stage.getHeight()*.7f);});check(Math.abs(service.snapshot().position-beforeCancel)<150,"cancelled lyric touch still committed a seek");actions.ui(()->browse(page[0]));helper.await(()->page[0].browseBar.getVisibility()==View.VISIBLE&&page[0].stage.browseStart()>0,"manual lyric browse did not expose confirmed seek/follow actions");int paused=service.snapshot().position;actions.screenshot("record-lyrics-browse.png");check(Math.abs(service.snapshot().position-paused)<150,"browsing lyrics sought native audio before confirmation");actions.ui(()->page[0].returnCurrent.performClick());check(page[0].stage.following()&&page[0].browseBar.getVisibility()==View.GONE&&Math.abs(service.snapshot().position-paused)<150,"return-current action changed audio position or kept browse controls");
            actions.ui(()->browse(page[0]));long target=page[0].stage.browseStart()+200;check(target>200,"browse confirmation has no timed target");actions.ui(()->page[0].seekLine.performClick());helper.await(()->Math.abs(service.snapshot().position-target)<650&&!service.snapshot().playing,"play-this-line did not seek native paused audio with track offset");
            actions.ui(()->{actions.event(page[0].stage,MotionEvent.ACTION_DOWN,page[0].stage.getWidth()/2f,page[0].stage.getHeight()*.8f);service.next();});helper.await(()->service.snapshot().ready&&page[0].trackUri().equals(uris.get(1)),"track change did not refresh record lyric session");actions.ui(()->actions.event(page[0].stage,MotionEvent.ACTION_UP,page[0].stage.getWidth()/2f,page[0].stage.getHeight()*.8f));check(service.snapshot().position<2000&&page[0].timing.offset()==0,"old lyric finger sought new track or leaked its offset");
            long generation=service.snapshot().generation;actions.ui(()->{actions.event(page[0].stage,MotionEvent.ACTION_DOWN,page[0].stage.getWidth()/2f,page[0].stage.getHeight()*.8f);PlaybackService.startQueue(context,queue,1,0,68,false,false,"high");});helper.await(()->service.snapshot().ready&&service.snapshot().generation>generation&&(Long)FullPortChecks.field(page[0],"observedGeneration")==service.snapshot().generation,"same-track replacement did not update lyric interaction identity");actions.ui(()->actions.event(page[0].stage,MotionEvent.ACTION_UP,page[0].stage.getWidth()/2f,page[0].stage.getHeight()*.8f));check(service.snapshot().position<2000,"old gesture sought a replacement session for the same URI");
            actions.ui(()->page[0].showTiming());SourcePlaylistUiChecks.click(test,"提前 0.2 秒");check(page[0].timing.offset()==-200,"inline timing action did not update current track");actions.ui(service::previous);helper.await(()->page[0].trackUri().equals(uris.get(0))&&service.snapshot().ready,"track switch while timing dialog was open failed");check(!((AlertDialog)FullPortChecks.field(page[0],"timingDialog")).isShowing()&&page[0].timing.offset()==200,"track timing dialog survived a different song or forgot its saved offset");
            helper.await(()->page[0].host.artwork(uris.get(0))!=null,"record lyric preview missing real fixture art");actions.ui(()->{service.pause();page[0].refresh();});actions.screenshot("record-lyrics-player.png");PlaybackService.Snapshot closing=service.snapshot();actions.ui(page[0]::dismiss);actions.ui(()->NowPlayingChecks.invoke(activity,"showNowPlaying"));page[0]=(NowPlayingDialog)FullPortChecks.field(activity,"nowPlayingDialog");helper.await(()->page[0].stage.appearance().style==4&&page[0].timing.offset()==200,"saved display/timing failed on page reopen");check(service.snapshot().player==closing.player&&service.snapshot().generation==closing.generation,"reopening record settings rebuilt native playback");
            System.out.println("MYGO_RECORD_LYRICS_OK: actual long-press settings/widgets and persistence, shared full-page style/offset updates, foreground animation suspension/resume, display-only defaults, browse without seek, confirmed offset-aware native seek and follow, stale cross-track/same-URI gesture rejection, timing-dialog invalidation, reopen retention and unchanged native player");
        }finally{actions.ui(()->{if(page[0]!=null)page[0].dismiss();LyricsStageDialog full=(LyricsStageDialog)FullPortChecks.field(activity,"lyricsStage");if(full!=null)full.dismiss();service.clearQueue();ArrayList<Uri> tracks=(ArrayList<Uri>)FullPortChecks.field(activity,"tracks");ArrayList<String> names=(ArrayList<String>)FullPortChecks.field(activity,"names");for(String value:uris){int at=tracks.indexOf(Uri.parse(value));if(at>=0){tracks.remove(at);names.remove(at);}}NowPlayingChecks.invoke(activity,"saveLibrary");activity.finish();});art.delete();restore(prefs,original);}
    }
